/**
 * Local media (public/media/…) generated by scripts/media/run.mjs: map images, agent icons, team logos and
 * player photos, with the source of every file. See docs/data.md ("Mídia").
 */
import gameMediaJson from './game/media.json';
import realMediaJson from './real/media.json';
import { publicUrl } from './publicUrl';

export interface MediaSource {
  /** Where the file came from (today always 'liquipedia'). */
  source: string;
  /** File description page (credit, license, history). */
  sourceUrl: string;
  /** Original file name at the source. */
  file: string;
  credit: string;
}

export interface MapMedia extends MediaSource {
  image: string;
}
export interface AgentMedia extends MediaSource {
  icon: string;
}
export interface TeamMedia extends MediaSource {
  logo: string;
  /** true: the logo Liquipedia shows for the team at that event; false: the team's current logo. */
  eraSpecific: boolean;
}
export interface PlayerMedia extends MediaSource {
  photo: string;
  /** true: a photo taken at that event (by file name); false: the player's current infobox photo. */
  eraSpecific: boolean;
  liquipediaId: string;
}

interface GameMediaJson {
  maps: Record<string, MapMedia>;
  agents: Record<string, AgentMedia>;
}
interface RealMediaJson {
  /** Keys: `${teamId}-${eventId}` (era-specific) or `${teamId}` (current logo). */
  teams: Record<string, TeamMedia>;
  /** Keys: `${playerId}@${eventId}` (era-specific) or `${playerId}` (current photo). */
  players: Record<string, PlayerMedia>;
}

const GAME_MEDIA = gameMediaJson as GameMediaJson;
const REAL_MEDIA = realMediaJson as RealMediaJson;

/**
 * Player photos inlined as data URLs, only in builds made with VITE_INLINE_PLAYER_PHOTOS=1 (the claude.ai preview,
 * which caps a page at 511 files). Regular builds serve them from public/ and leave this map empty.
 */
const INLINE_PLAYER_PHOTOS: Record<string, string> =
  import.meta.env?.VITE_INLINE_PLAYER_PHOTOS === '1'
    ? import.meta.glob<string>('../../public/media/players/*.webp', { query: '?inline', import: 'default', eager: true })
    : {};

/** Public URL of a path under public/ (honours Vite's base), or the inlined data URL of a player photo. */
export function mediaUrl(path: string): string {
  const inlined = INLINE_PLAYER_PHOTOS[`../../public/${path}`];
  return inlined ?? publicUrl(path);
}

export const mapMedia = (name: string): MapMedia | undefined => GAME_MEDIA.maps[name];
export const agentMedia = (name: string): AgentMedia | undefined => GAME_MEDIA.agents[name];

/** Logo of a team at an event: the era logo when known, else the team's current one. */
export function teamMedia(teamId: string, eventId?: string): TeamMedia | undefined {
  return (eventId ? REAL_MEDIA.teams[`${teamId}-${eventId}`] : undefined) ?? REAL_MEDIA.teams[teamId];
}

/** Photo of a player: taken at the event when the source has one, else the current photo. */
export function playerMedia(playerId: string, eventId?: string): PlayerMedia | undefined {
  return (eventId ? REAL_MEDIA.players[`${playerId}@${eventId}`] : undefined) ?? REAL_MEDIA.players[playerId];
}

let photosByPlayer: Map<string, { eventId: string | null; media: PlayerMedia }[]> | null = null;

/** Every photo of a player: one per event it was taken at (`eventId`), and the current one (`eventId` null). */
export function playerPhotos(playerId: string): readonly { eventId: string | null; media: PlayerMedia }[] {
  if (!photosByPlayer) {
    photosByPlayer = new Map();
    for (const [key, media] of Object.entries(REAL_MEDIA.players)) {
      const at = key.indexOf('@');
      const id = at < 0 ? key : key.slice(0, at);
      const list = photosByPlayer.get(id) ?? [];
      list.push({ eventId: at < 0 ? null : key.slice(at + 1), media });
      photosByPlayer.set(id, list);
    }
  }
  return photosByPlayer.get(playerId) ?? [];
}

export const MEDIA_COUNTS = {
  maps: Object.keys(GAME_MEDIA.maps).length,
  agents: Object.keys(GAME_MEDIA.agents).length,
  teams: Object.keys(REAL_MEDIA.teams).length,
  players: Object.keys(REAL_MEDIA.players).length,
};
